mapper.select:
SELECT id, open_id, game_mode, difficulty, index, puzzle, candidates, time_elapsed, status, miss_count, hint_count, create_time, update_time
FROM sudoku
WHERE id = #{id}

SELECT id, open_id, game_mode, difficulty, index, puzzle, candidates, time_elapsed, status, miss_count, hint_count, create_time, update_time
FROM sudoku
WHERE open_id = #{openId} and game_mode = #{gameMode} and difficulty = #{difficulty} and index = #{index}

SELECT id, open_id, game_mode, difficulty, index, puzzle, candidates, time_elapsed, status, miss_count, hint_count, create_time, update_time
FROM sudoku where open_id = #{openId} and game_mode = #{gameMode}
ORDER BY create_time DESC
